mapper.insert:
INSERT INTO heartbeat_event(device_id, source_event_id, reported_at, received_at)
SELECT id, #{eventId}, #{reported}, UTC_TIMESTAMP(3) FROM device WHERE device_no = #{deviceNo}
ON DUPLICATE KEY UPDATE id = heartbeat_event.id

mapper.select:
SELECT d.id, d.device_no, COALESCE(s.state, 'NEVER'), s.last_received_at
FROM device d LEFT JOIN device_status s ON s.device_id = d.id
WHERE d.id > #{afterId}
AND COALESCE(s.state, 'NEVER') = #{state}
ORDER BY d.id LIMIT #{limit}
